    /// This is an assumption we're making about flags.  Probably these flags can never be
    /// changed, but let's check just in case.
    #[test]
    fn linux_flags_assumptions() {
        assert_eq!(libc::SOCK_NONBLOCK, OFlag::O_NONBLOCK.bits());
        assert_eq!(libc::SOCK_CLOEXEC, OFlag::O_CLOEXEC.bits());
    }

    #[test]
    fn pipe_capacity_failure_classifies_the_errno() {
        let created = [17, 18];

        // The only success shape: Linux applied EXACTLY the capacity we asked for.
        assert_eq!(
            pipe_capacity_failure(created, Ok(i64::from(deterministic_pipe_capacity_bytes()))),
            None
        );

        // Successful-but-wrong capacity is a pipe whose size we did not choose. That is not a
        // kernel errno, so it is reported as EIO rather than dressed up as one.
        let mismatch = pipe_capacity_failure(
            created,
            Ok(i64::from(deterministic_pipe_capacity_bytes()) * 2),
        )
        .expect("a capacity Linux rounded away from the pin must not read as success");
        assert_eq!(mismatch.created_fds, created);
        assert_eq!(mismatch.error, Errno::EIO);

        // A real kernel errno is preserved rather than rewritten.
        let denied = pipe_capacity_failure(created, Err(Errno::EPERM))
            .expect("a kernel refusal must not read as success");
        assert_eq!(denied.created_fds, created);
        assert_eq!(denied.error, Errno::EPERM);

        // The descriptors are carried through every failure shape, because they are what the
        // caller has to close; losing them here is how they would leak.
        assert_eq!(denied.created_fds, created);
    }

    #[test]
    fn pipe_capacity_failure_closes_both_created_descriptors() {
        if isolated_child(
            "syscalls::files::test::pipe_capacity_failure_closes_both_created_descriptors",
        ) {
            return;
        }
        let mut created = [-1; 2];
        assert_eq!(
            unsafe { libc::pipe2(created.as_mut_ptr(), libc::O_CLOEXEC) },
            0
        );

        let pin_result = unsafe { libc::fcntl(created[0], libc::F_SETPIPE_SZ, -1) };
        assert_eq!(pin_result, -1);
        let pin_error = Errno::last();
        // Pin the errno, not just the failure. Without this the test asserts only that
        // `fcntl` returned -1, so it would still pass if the call failed for a reason we
        // did not engineer -- an invalid `created[0]` fails EBADF, every assertion below
        // still holds, and the capacity-pin path is never exercised at all.
        //
        // EINVAL is structural here, not a property of this host. `fcntl`'s argument is an
        // `unsigned long`, so -1 arrives as ULONG_MAX; `round_pipe_size` returns 0 for any
        // size above 2^31, and `pipe_set_size` maps that 0 to -EINVAL BEFORE it consults
        // `CAP_SYS_RESOURCE`. So the result does not depend on privilege or on
        // `/proc/sys/fs/pipe-max-size`.
        assert_eq!(pin_error, Errno::EINVAL);

        let failure = pipe_capacity_failure(created, Err(pin_error))
            .expect("the forced capacity-pin failure must enter the cleanup path");
        for close in failure.close_syscalls() {
            assert_eq!(unsafe { libc::close(close.fd()) }, 0);
        }

        for fd in created {
            assert_eq!(unsafe { libc::fcntl(fd, libc::F_GETFD) }, -1);
            assert_eq!(Errno::last(), Errno::EBADF);
        }
    }

    #[test]
    fn rendered_procfs_seek_follows_each_llseek() {
        use super::RenderedSeek::*;
        // generic_file_llseek (auxv, cmdline): SEEK_DATA and SEEK_HOLE at any
        // offset of a file of size 0, a negative one included, are ENXIO.
        for whence in [Whence::SEEK_DATA, Whence::SEEK_HOLE] {
            for offset in [i64::MIN, -1, 0, 1, i64::MAX] {
                assert_eq!(
                    super::rendered_procfs_seek(Generic, whence, offset, 0),
                    Err(Errno::ENXIO)
                );
            }
            assert_eq!(
                super::rendered_procfs_seek(Default, whence, 0, 0),
                Err(Errno::ENXIO)
            );
            assert_eq!(
                super::rendered_procfs_seek(SeqFile, whence, -1, 0),
                Err(Errno::EINVAL)
            );
        }
        // default_llseek compares signed: a negative SEEK_DATA offset stays
        // negative (EINVAL); a negative SEEK_HOLE offset becomes the size, 0.
        assert_eq!(
            super::rendered_procfs_seek(Default, Whence::SEEK_DATA, -1, 0),
            Err(Errno::EINVAL)
        );
        assert_eq!(
            super::rendered_procfs_seek(Default, Whence::SEEK_HOLE, -1, 5),
            Ok(0)
        );
        // vfs_setpos: s_maxbytes (MAX_NON_LFS) bounds generic_file_llseek only.
        let max = (1_i64 << 31) - 1;
        assert_eq!(
            super::rendered_procfs_seek(Generic, Whence::SEEK_SET, max, 0),
            Ok(max as usize)
        );
        assert_eq!(
            super::rendered_procfs_seek(Generic, Whence::SEEK_SET, max + 1, 0),
            Err(Errno::EINVAL)
        );
        assert_eq!(
            super::rendered_procfs_seek(Generic, Whence::SEEK_CUR, 1, max as usize),
            Err(Errno::EINVAL)
        );
        assert_eq!(
            super::rendered_procfs_seek(Default, Whence::SEEK_SET, max + 1, 0),
            Ok(max as usize + 1)
        );
        assert_eq!(
            super::rendered_procfs_seek(Generic, Whence::SEEK_SET, -1, 0),
            Err(Errno::EINVAL)
        );
        assert_eq!(
            super::rendered_procfs_seek(Generic, Whence::SEEK_END, 3, 0),
            Ok(3)
        );
        assert_eq!(
            super::rendered_procfs_seek(SeqFile, Whence::SEEK_END, 0, 0),
            Err(Errno::EINVAL)
        );
        assert_eq!(
            super::rendered_procfs_seek(Generic, Whence::from_raw(99), 0, 0),
            Err(Errno::EINVAL)
        );
        // A sum past LLONG_MAX wraps negative in `loff_t`: EINVAL for a
        // seq_file and a sysctl file alike, never EOVERFLOW. LLONG_MAX itself
        // is a position.
        let end = i64::MAX as usize;
        assert_eq!(
            super::rendered_procfs_seek(SeqFile, Whence::SEEK_SET, i64::MAX, 4),
            Ok(end)
        );
        for seek in [SeqFile, Default] {
            assert_eq!(
                super::rendered_procfs_seek(seek, Whence::SEEK_CUR, i64::MAX, 4),
                Err(Errno::EINVAL)
            );
            assert_eq!(
                super::rendered_procfs_seek(seek, Whence::SEEK_CUR, 1, end),
                Err(Errno::EINVAL)
            );
            assert_eq!(
                super::rendered_procfs_seek(seek, Whence::SEEK_CUR, 0, end),
                Ok(end)
            );
        }
    }

    /// The reason Detcore gives where it refuses a read or a seek of a
    /// per-process file whose record sequence it cannot know here
    /// (`Detcore::refuse_unknown_record_sequence`) names the descriptor, the
    /// file where Detcore knows it, and why.
    #[test]
    fn an_unknown_record_sequence_is_refused_by_name() {
        let reason =
            super::unknown_record_sequence_reason(5, Some(std::path::Path::new("/proc/7/statm")));
        for part in [
            "descriptor 5, the per-process file /proc/7/statm,",
            "over SCM_RIGHTS",
            "the one open file every process holding it shares",
            "neither reads nor seeks it",
        ] {
            assert!(reason.contains(part), "{part}: {reason}");
        }
        assert!(
            super::unknown_record_sequence_reason(5, None)
                .contains("descriptor 5, a per-process /proc file,")
        );
        // The refusal ends the run wherever that ends it: not where the
        // fail-closed exit would end only a guest process from inside its
        // tool (SaBRe's capabilities), where the call gets EOPNOTSUPP instead.
        let config = |backend, shutdown| crate::Config {
            backend,
            shutdown_on_unsupported_syscall: shutdown,
            ..crate::Config::default()
        };
        assert!(super::refusal_would_strand_the_run(&config(
            reverie::BackendCapabilities::SABRE,
            true
        )));
        for (backend, shutdown) in [
            (reverie::BackendCapabilities::SABRE, false),
            (reverie::BackendCapabilities::DBT, false),
            (reverie::BackendCapabilities::PTRACE, true),
            (reverie::BackendCapabilities::KVM, true),
        ] {
            assert!(!super::refusal_would_strand_the_run(&config(
                backend, shutdown
            )));
        }
    }

    #[test]
    fn random_device_lseek_matches_linux_noop_llseek() {
        for whence in [
            Whence::SEEK_SET,
            Whence::SEEK_CUR,
            Whence::SEEK_END,
            Whence::SEEK_DATA,
            Whence::SEEK_HOLE,
        ] {
            for status_flags in [
                OFlag::empty().bits(),
                OFlag::O_WRONLY.bits(),
                OFlag::O_RDWR.bits(),
            ] {
                assert_eq!(random_device_lseek_result(status_flags, whence), Ok(0));
            }
            assert_eq!(
                random_device_lseek_result(OFlag::O_PATH.bits(), whence),
                Err(Errno::EBADF)
            );
        }
        assert_eq!(
            random_device_lseek_result(OFlag::empty().bits(), Whence::from_raw(99)),
            Err(Errno::EINVAL)
        );
        assert_eq!(
            random_device_lseek_result(OFlag::O_PATH.bits(), Whence::from_raw(99)),
            Err(Errno::EBADF)
        );
    }

    #[test]
    fn timer_slack_write_parser_matches_decimal_procfs_contract() {
        assert_eq!(parse_timer_slack_write(b"0"), Ok(0));
        assert_eq!(parse_timer_slack_write(b"+123\n"), Ok(123));
        assert_eq!(parse_timer_slack_write(b"456\0ignored"), Ok(456));
        assert_eq!(
            parse_timer_slack_write(u64::MAX.to_string().as_bytes()),
            Ok(u64::MAX)
        );

        for invalid in [b"".as_slice(), b"+", b"-1", b" 1", b"1 ", b"1\n2", b"0x10"] {
            assert_eq!(parse_timer_slack_write(invalid), Err(Errno::EINVAL));
        }
        assert_eq!(
            parse_timer_slack_write(b"18446744073709551616"),
            Err(Errno::ERANGE)
        );
    }

    #[test]
    fn timer_slack_vectored_offset_preserves_minus_one_sentinel() {
        assert_eq!(vectored_offset(u64::MAX, u64::MAX), -1);
        assert_eq!(vectored_offset(0, 0), 0);
        assert_eq!(vectored_offset(7, 0), 7);
    }

    #[test]
    fn timer_slack_binding_rejects_exit_reuse_and_other_tasks() {
        let binding = TimerSlackBinding {
            target: 202,
            device: 11,
            inode: 22,
        };
        assert_eq!(
            classify_timer_slack_binding(binding, Some((11, 22)), 202),
            Ok(())
        );
        assert_eq!(
            classify_timer_slack_binding(binding, Some((11, 22)), 303),
            Err(Errno::EPERM)
        );
        assert_eq!(
            classify_timer_slack_binding(binding, None, 202),
            Err(Errno::ESRCH)
        );
        assert_eq!(
            classify_timer_slack_binding(binding, Some((11, 23)), 202),
            Err(Errno::ESRCH),
            "a recycled numeric TID must not revive an old proc inode"
        );
    }

